export const paymentLabels={credit:'เครดิต',cash:'เงินสด'};
export const statuses={pending:'รออนุมัติ',approved:'รอรับสินค้า',received:'รอใบกำกับภาษี',closed:'ปิดใบ PO แล้ว',rejected:'ไม่อนุมัติ'};
export const actionLabels={create:'เปิดใบ PO',approve:'อนุมัติ',reject:'ไม่อนุมัติ',receive:'ได้รับสินค้าครบแล้ว',close:'ได้รับใบกำกับภาษีและปิด PO'};
export const money=n=>new Intl.NumberFormat('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n||0)/100);
export const date=s=>new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(s));
export const poDate=s=>new Intl.DateTimeFormat('th-TH',{dateStyle:'long',timeZone:'Asia/Bangkok'}).format(new Date(`${s}T12:00:00+07:00`));
export const monthLabel=s=>new Intl.DateTimeFormat('th-TH',{month:'long',year:'numeric',timeZone:'Asia/Bangkok'}).format(new Date(`${s}-01T12:00:00+07:00`));
export function todayBangkok(now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Bangkok'}).formatToParts(now);return `${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}-${parts.find(p=>p.type==='day').value}`;}
export function scaled(value,digits){const s=String(value).trim();if(!new RegExp(`^\\d{1,9}(?:\\.\\d{1,${digits}})?$`).test(s))throw Error('กรอกตัวเลขบวก และทศนิยมไม่เกิน '+digits+' ตำแหน่ง');const [a,b='']=s.split('.');return BigInt(a+b.padEnd(digits,'0'));}
export function validatePODate(value){const s=String(value||''),match=/^(20\d{2})-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.exec(s);if(!match)throw Error('เลือกวันที่ของใบ PO ให้ถูกต้อง');const year=Number(match[1]),month=Number(match[2]),day=Number(match[3]),check=new Date(Date.UTC(year,month-1,day));if(check.getUTCFullYear()!==year||check.getUTCMonth()!==month-1||check.getUTCDate()!==day)throw Error('เลือกวันที่ของใบ PO ให้ถูกต้อง');return s;}
export function validateItems(items){if(!Array.isArray(items)||!items.length||items.length>50)throw Error('ระบุสินค้า 1–50 รายการ');return items.map((i,index)=>{try{const name=String(i.name||'').trim(),spec=String(i.spec||'').trim(),source=String(i.source||'').trim(),note=String(i.note||'').trim(),itemUnit=String(i.unit??'ชิ้น').trim(),department=String(i.department||'').trim();if(department.length>100)throw Error('ชื่อแผนก/สาขาต้องไม่เกิน 100 ตัวอักษร');if(!name||name.length>200)throw Error('ระบุชื่อสินค้าไม่เกิน 200 ตัวอักษร');if(!spec||spec.length>2000)throw Error('ระบุรายละเอียด / สเปคไม่เกิน 2,000 ตัวอักษร');if(!source||source.length>300)throw Error('ระบุแหล่งซื้อไม่เกิน 300 ตัวอักษร');if(!itemUnit||itemUnit.length>50)throw Error('ระบุหน่วยไม่เกิน 50 ตัวอักษร');if(note.length>2000)throw Error('หมายเหตุต้องไม่เกิน 2,000 ตัวอักษร');const payment_method=i.payment_method??'';if(typeof payment_method!=='string'||(payment_method!==''&&!Object.hasOwn(paymentLabels,payment_method)))throw Error('เลือกการชำระเงินเป็นเครดิตหรือเงินสด');const q=scaled(i.qty,3),unitPrice=scaled(i.unit_price,2);if(q<=0n||q>1000000000n)throw Error('จำนวนต้องมากกว่า 0 และไม่เกิน 1,000,000');if(unitPrice<=0n||unitPrice>100000000000n)throw Error('ราคาต่อหน่วยต้องมากกว่า 0 และไม่เกิน 1,000,000,000');const total=Number((q*unitPrice+500n)/1000n);if(total<=0||total>100000000000)throw Error('ยอดต่อรายการต้องอยู่ระหว่าง 0.01 ถึง 1,000,000,000 บาท');const base=i.vat?Number((BigInt(total)*100n+53n)/107n):total;return {department,name,spec,source,note,payment_method,qty:String(i.qty),unit:itemUnit,unit_price:String(i.unit_price),vat:!!i.vat,base_cents:base,tax_cents:total-base,total_cents:total};}catch(e){throw Object.assign(Error(`รายการ ${index+1}: ${e.message}`),{index});}});}
export function totals(items){return items.reduce((a,i)=>({base_cents:a.base_cents+i.base_cents,tax_cents:a.tax_cents+i.tax_cents,total_cents:a.total_cents+i.total_cents}),{base_cents:0,tax_cents:0,total_cents:0});}
export function vatBase(items){return items.reduce((sum,item)=>sum+(item.vat?item.base_cents:0),0);}
export function transition(po,action,actor,reason='',invoiceConfirmed=false){const rules={approve:['owner','pending','approved'],reject:['owner','pending','rejected'],receive:['office','approved','received'],close:['owner','received','closed']};const rule=rules[action];if(!rule||actor.role!==rule[0])throw Error('บัญชีนี้ไม่มีสิทธิ์ทำรายการ');if(action==='receive'&&!actor.can_export_report&&po.created_by!==actor.id)throw Error('รับสินค้าได้เฉพาะใบ PO ของตนเอง');if(po.status!==rule[1])throw Error('สถานะเปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');if(action==='reject'&&!reason.trim())throw Error('ระบุเหตุผลที่ไม่อนุมัติ');if(reason.length>2000)throw Error('เหตุผลต้องไม่เกิน 2,000 ตัวอักษร');if(action==='close'&&!invoiceConfirmed)throw Error('ต้องยืนยันว่าได้รับใบกำกับภาษีแล้ว');const now=new Date().toISOString();return {...po,status:rule[2],version:po.version+1,rejection_reason:action==='reject'?reason:po.rejection_reason,invoice_confirmed:action==='close'||po.invoice_confirmed,approved_at:action==='approve'?now:po.approved_at,events:[...(po.events||[]),{action,actor_name:actor.display_name,at:now,reason}]};}
export function summarizeMonth(rows){const ordered=rows.filter(r=>['approved','received','closed'].includes(r.status));return {rows,total_cents:ordered.reduce((sum,r)=>sum+r.total_cents,0),ordered_count:ordered.length,pending_count:rows.filter(r=>r.status==='pending').length,rejected_count:rows.filter(r=>r.status==='rejected').length};}
